    "fichaId": "iso-12207",
    "fichaTitulo": "ABNT NBR ISO/IEC/IEEE 12207:2021 — processos do ciclo de vida do software",
    "zonaId": "04-engenharia-de-software",
    "regiaoId": "floresta-do-codigo",
